import math
from collections import OrderedDict, defaultdict
src='/task/input/structure.pdb'
out='/task/work/final_caps.pdb'
standard=set('ALA ARG ASN ASP CYS GLN GLU GLY HIS ILE LEU LYS MET PHE PRO SER THR TRP TYR VAL'.split())
# parse residues in file order
residues=OrderedDict()
for line in open(src):
    if line.startswith(('ATOM','HETATM')):
        resn=line[17:20].strip()
        if resn not in standard and resn!='MSE':
            continue
        chain=line[21].strip()
        resseq=line[22:26].strip()
        icode=line[26].strip()
        key=(chain,resseq,icode)
        if key not in residues:
            residues[key]={'resn':resn,'lines':[]}
        residues[key]['lines'].append(line.rstrip('\n'))
print('Parsed residues:', len(residues))
# choose highest average occupancy altloc per residue
def choose_alt(lines):
    scores=defaultdict(list)
    for l in lines:
        alt=l[16].strip()
        occ=l[54:60].strip()
        if alt and occ:
            scores[alt].append(float(occ))
    if not scores:
        return ''
    return max(scores, key=lambda a: sum(scores[a])/len(scores[a]))
# clean residues, heavy atoms only
clean={}
for key,data in residues.items():
    alt_choice=choose_alt(data['lines'])
    atoms={}
    for l in data['lines']:
        alt=l[16].strip()
        if alt and alt!=alt_choice:
            continue
        name=l[12:16].strip()
        elem=l[76:78].strip()
        if elem=='H' or name.startswith('H'):
            continue
        occ=float(l[54:60]) if l[54:60].strip() else 0.0
        if name not in atoms or occ>atoms[name][0]:
            atoms[name]=(occ,l)
    clean[key]={'resn':data['resn'],'atoms':atoms}
# helper coordinate
def coord(key, atom):
    return tuple(float(clean[key]['atoms'][atom][1][i:i+8]) for i in (30,38,46))
def norm(v):
    n=math.sqrt(sum(x*x for x in v))
    return tuple(x/n for x in v) if n else (1.0,0.0,0.0)
def add(a,b): return tuple(x+y for x,y in zip(a,b))
def sub(a,b): return tuple(x-y for x,y in zip(a,b))
def mul(a,s): return tuple(x*s for x in a)
def cross(a,b): return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])
# cap coordinates derived from adjacent backbone
c36=coord(('P','36',''),'C'); ca36=coord(('P','36',''),'CA')
n41=coord(('P','41',''),'N'); ca41=coord(('P','41',''),'CA')
u1=norm(sub(c36,ca36))
nme_n=add(c36,mul(u1,1.33))
nme_c=add(nme_n,mul(u1,1.45))
u2=norm(sub(n41,ca41))
ace_c=add(n41,mul(u2,1.33))
ace_ch3=add(ace_c,mul(u2,1.52))
p=norm(cross(u2,(0.0,0.0,1.0)))
if p==(0,0,0): p=norm(cross(u2,(1.0,0.0,0.0)))
o_dir=norm(add(mul(u2,math.cos(math.radians(120))),mul(p,math.sin(math.radians(120)))))
ace_o=add(ace_c,mul(o_dir,1.23))
# output PDB with sequential residue numbers and atom serials
out_lines=[]
serial=0
resnum=0
mapping={}
def atom_line(name,resname,resnum,x,y,z,element):
    global serial
    serial+=1
    return f"ATOM  {serial:5d} {name:<4s} {resname:>3s} P{resnum:4d}    {x:8.3f}{y:8.3f}{z:8.3f}  1.00  0.00          {element:>2s}"
def emit_residue(key, override_resn=None):
    global resnum
    resnum+=1
    data=clean[key]
    resn=override_resn or data['resn']
    mapping[resnum]=(key[0],key[1],key[2],resn)
    for name in data['atoms']:
        l=data['atoms'][name][1]
        x,y,z=float(l[30:38]),float(l[38:46]),float(l[46:54])
        elem=l[76:78].strip()
        if resn=='MET' and name=='SE':
            name='SD'; elem='S'
        out_lines.append(atom_line(name,resn,resnum,x,y,z,elem))
# iterate in original order and insert caps around gap
nme_done=False; ace_done=False
for key,data in clean.items():
    chain,resseq,icode=key
    if (chain,resseq,icode)==('P','41','') and not ace_done:
        # ACE cap before residue 41
        resnum+=1
        mapping[resnum]=('P','41','','ACE_cap')
        out_lines.append(atom_line('CH3','ACE',resnum,*ace_ch3,'C'))
        out_lines.append(atom_line('C','ACE',resnum,*ace_c,'C'))
        out_lines.append(atom_line('O','ACE',resnum,*ace_o,'O'))
        ace_done=True
        out_lines.append('TER')
    # determine residue name
    resn=data['resn']
    if resn=='MSE':
        resn='MET'
    if (chain,resseq,icode) in [('P','22',''),('P','31',''),('P','47',''),('P','55',''),('P','67A',''),('P','70','')]:
        resn='CYX'
    emit_residue(key,resn)
    if (chain,resseq,icode)==('P','36','') and not nme_done:
        # NME cap after residue 36
        resnum+=1
        mapping[resnum]=('P','36','','NME_cap')
        out_lines.append(atom_line('N','NME',resnum,*nme_n,'N'))
        out_lines.append(atom_line('C','NME',resnum,*nme_c,'C'))
        nme_done=True
        out_lines.append('TER')
out_lines.append('TER')
out_lines.append('END')
open(out,'w').write('\n'.join(out_lines)+'\n')
print('Wrote',out,'atoms',serial,'residues',resnum)
print('Mapping cap/sequence around break:')
for k in sorted(mapping):
    if k in (19,20,21,22): print(k,mapping[k])
print('Disulfide residue mappings:')
for k,v in mapping.items():
    if v[3]=='CYX': print(k,v)
